Конечно! Для создания красивого UI на C# лучше всего подойдет **WPF** (Windows Presentation Foundation). Он позволяет легко стилизовать элементы, использовать скругления, тени и современные цвета, в отличие от устаревшего Windows Forms.

Ниже представлен полный код современного калькулятора в темной теме, а также батник для автоматической сборки и запуска.

### 1. Код приложения

Создайте файл `Calculator.cs` в новой папке. Этот файл содержит всю логику и разметку XAML внутри себя (для удобства запуска одним файлом через `dotnet run`).

```csharp
// Calculator.cs
using System;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Shapes;

namespace ModernCalculator
{
    public class App : Application
    {
        [STAThread]
        public static void Main()
        {
            var app = new App();
            app.InitializeComponent();
            app.Run(new CalculatorWindow());
        }

        protected override void OnStartup(StartupEventArgs e)
        {
            base.OnStartup(e);
        }
    }

    public class CalculatorWindow : Window
    {
        private TextBlock _displayCurrent;
        private TextBlock _displayHistory;
        private double _num1 = 0;
        private string _operator = "";
        private bool _isNewEntry = true;

        public CalculatorWindow()
        {
            Title = "Modern Calculator";
            Width = 340;
            Height = 520;
            ResizeMode = ResizeMode.NoResize;
            Background = new SolidColorBrush(Color.FromRgb(30, 30, 30)); // Dark Gray
            WindowStyle = WindowStyle.None; // Безрамочное окно для красоты
            AllowsTransparency = true;
            BorderBrush = new SolidColorBrush(Color.FromRgb(60, 60, 60));
            BorderThickness = new Thickness(1);

            // Кастомная панель перетаскивания
            MouseLeftButtonDown += (s, e) => DragMove();

            var grid = new Grid { Margin = new Thickness(10) };

            // Определение строк и колонок
            for (int i = 0; i < 5; i++) 
                grid.RowDefinitions.Add(new RowDefinition { Height = i == 0 ? new GridLength(100) : new GridLength(1, GridUnitType.Star) });
            for (int i = 0; i < 4; i++) 
                grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

            // Дисплей
            var displayStack = new StackPanel { VerticalAlignment = VerticalAlignment.Bottom, Margin = new Thickness(10, 0, 10, 10) };
            _displayHistory = new TextBlock { Text = "", FontSize = 16, Foreground = Brushes.Gray, HorizontalAlignment = HorizontalAlignment.Right };
            _displayCurrent = new TextBlock { Text = "0", FontSize = 42, FontWeight = FontWeights.Light, Foreground = Brushes.White, HorizontalAlignment = HorizontalAlignment.Right };
            displayStack.Children.Add(_displayHistory);
            displayStack.Children.Add(_displayCurrent);
            Grid.SetRow(displayStack, 0);
            Grid.SetColumnSpan(displayStack, 4);
            grid.Children.Add(displayStack);

            // Кнопки
            string[,] buttons = {
                { "C", "±", "%", "÷" },
                { "7", "8", "9", "×" },
                { "4", "5", "6", "-" },
                { "1", "2", "3", "+" },
                { "0", ".", "⌫", "=" }
            };

            for (int r = 0; r < 5; r++)
            {
                for (int c = 0; c < 4; c++)
                {
                    var btn = CreateButton(buttons[r, c]);
                    Grid.SetRow(btn, r + 1); // +1 т.к. 0 ряд занят дисплеем (визуально мы отступили, но в гриде это важно)
                    // Корректировка: дисплей в Row 0, кнопки начинаются с Row 1
                    // Но у нас 5 рядов кнопок. Исправим структуру грида выше.
                    // Проще сделать отдельный грид для кнопок.
                }
            }

            // Переделаем структуру для чистоты: Верх - дисплей, Низ - грид кнопок
            var mainStack = new StackPanel();
            mainStack.Children.Add(displayStack);

            var btnGrid = new Grid { Margin = new Thickness(5) };
            for (int i = 0; i < 5; i++) btnGrid.RowDefinitions.Add(new RowDefinition());
            for (int i = 0; i < 4; i++) btnGrid.ColumnDefinitions.Add(new ColumnDefinition());

            for (int r = 0; r < 5; r++)
            {
                for (int c = 0; c < 4; c++)
                {
                    var btn = CreateButton(buttons[r, c]);
                    Grid.SetRow(btn, r);
                    Grid.SetColumn(btn, c);
                    btnGrid.Children.Add(btn);
                }
            }
            mainStack.Children.Add(btnGrid);
            Content = mainStack;
        }

        private Button CreateButton(string content)
        {
            var btn = new Button
            {
                Content = content,
                FontSize = 20,
                Margin = new Thickness(3),
                BorderThickness = new Thickness(0),
                Cursor = System.Windows.Input.Cursors.Hand,
                Template = GetRoundedTemplate()
            };

            // Цветовая схема
            Color bg = Color.FromRgb(50, 50, 50); // Обычные цифры
            Color fg = Colors.White;

            if (content == "=") { bg = Color.FromRgb(255, 159, 10); fg = Colors.Black; } // Orange accent
            else if ("÷×-+".Contains(content)) { bg = Color.FromRgb(70, 70, 70); fg = Color.FromRgb(255, 159, 10); }
            else if (content == "C" || content == "⌫") { bg = Color.FromRgb(70, 70, 70); }

            btn.Background = new SolidColorBrush(bg);
            btn.Foreground = new SolidColorBrush(fg);

            // Hover эффект
            btn.MouseEnter += (s, e) => btn.Opacity = 0.8;
            btn.MouseLeave += (s, e) => btn.Opacity = 1.0;

            btn.Click += Button_Click;
            return btn;
        }

        private ControlTemplate GetRoundedTemplate()
        {
            var factory = new FrameworkElementFactory(typeof(Border));
            factory.SetValue(Border.CornerRadiusProperty, new CornerRadius(8));
            factory.SetValue(Border.BackgroundProperty, new TemplateBindingExtension(Button.BackgroundProperty));
            var cp = new FrameworkElementFactory(typeof(ContentPresenter));
            cp.SetValue(ContentPresenter.HorizontalAlignmentProperty, HorizontalAlignment.Center);
            cp.SetValue(ContentPresenter.VerticalAlignmentProperty, VerticalAlignment.Center);
            factory.AppendChild(cp);
            var template = new ControlTemplate(typeof(Button)) { VisualTree = factory };
            return template;
        }

        private void Button_Click(object sender, RoutedEventArgs e)
        {
            var btn = (Button)sender;
            string val = btn.Content.ToString();

            if (val == "C") { Reset(); return; }
            if (val == "⌫") { Backspace(); return; }
            if (val == "±") { ToggleSign(); return; }
            if (val == "%") { Percent(); return; }

            if ("0123456789.".Contains(val))
            {
                if (_isNewEntry) { _displayCurrent.Text = (val == ".") ? "0." : val; _isNewEntry = false; }
                else 
                {
                    if (val == "." && _displayCurrent.Text.Contains(".")) return;
                    if (_displayCurrent.Text == "0" && val != ".") _displayCurrent.Text = val;
                    else _displayCurrent.Text += val;
                }
            }
            else if ("+-×÷".Contains(val))
            {
                if (!_isNewEntry && _operator != "") Calculate();
                _num1 = double.Parse(_displayCurrent.Text.Replace(',', '.'));
                _operator = val;
                _displayHistory.Text = $"{FormatNumber(_num1)} {val}";
                _isNewEntry = true;
            }
            else if (val == "=")
            {
                Calculate();
                _displayHistory.Text = "";
                _operator = "";
                _isNewEntry = true;
            }
        }

        private void Calculate()
        {
            double num2 = double.Parse(_displayCurrent.Text.Replace(',', '.'));
            double result = 0;
            switch (_operator)
            {
                case "+": result = _num1 + num2; break;
                case "-": result = _num1 - num2; break;
                case "×": result = _num1 * num2; break;
                case "÷": result = (num2 != 0) ? _num1 / num2 : 0; break;
            }
            _displayCurrent.Text = FormatNumber(result);
            _num1 = result;
        }

        private void Reset() { _displayCurrent.Text = "0"; _displayHistory.Text = ""; _num1 = 0; _operator = ""; _isNewEntry = true; }
        private void Backspace() 
        { 
            if (_isNewEntry) return;
            string t = _displayCurrent.Text;
            _displayCurrent.Text = t.Length > 1 ? t.Substring(0, t.Length - 1) : "0";
            if (_displayCurrent.Text == "0") _isNewEntry = true;
        }
        private void ToggleSign() 
        { 
            double v = double.Parse(_displayCurrent.Text.Replace(',', '.')); 
            _displayCurrent.Text = FormatNumber(-v); 
        }
        private void Percent() 
        { 
            double v = double.Parse(_displayCurrent.Text.Replace(',', '.')); 
            _displayCurrent.Text = FormatNumber(v / 100.0); 
            _isNewEntry = true;
        }

        private string FormatNumber(double val)
        {
            string s = val.ToString("G15").Replace('.', ',');
            return s;
        }
    }
}
```

### 2. Файл проекта

Создайте файл `Calculator.csproj` рядом с `Calculator.cs`:

```xml
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>WinExe</OutputType>
    <TargetFramework>net8.0-windows</TargetFramework>
    <UseWPF>true</UseWPF>
    <StartupObject>ModernCalculator.App</StartupObject>
    <!-- Убираем консольное окно при запуске -->
    <DisableWinExeOutputRedirection>true</DisableWinExeOutputRedirection>
  </PropertyGroup>
</Project>
```

### 3. Батник для сборки и запуска (`run.bat`)

Этот скрипт проверит наличие .NET SDK, соберет проект в Release-режиме и запустит его.

```bat
@echo off
chcp 65001 >nul
title Modern Calculator Builder

echo ==========================================
echo   Сборка и запуск калькулятора...
echo ==========================================

:: Проверка наличия dotnet
where dotnet >nul 2>nul
if %ERRORLEVEL% NEQ 0 (
    echo [ОШИБКА] .NET SDK не найден!
    echo Пожалуйста, установите .NET 8 SDK: https://dotnet.microsoft.com/download
    pause
    exit /b 1
)

echo [1/2] Сборка проекта (Release)...
dotnet build -c Release --nologo -v q
if %ERRORLEVEL% NEQ 0 (
    echo [ОШИБКА] Не удалось собрать проект. Проверьте код.
    pause
    exit /b 1
)

echo [2/2] Запуск приложения...
echo ------------------------------------------
start "" "bin\Release\net8.0-windows\Calculator.exe"

echo Приложение успешно запущено!
exit /b 0
```

### Как пользоваться:
1. Создайте пустую папку.
2. Положите в неё три файла: `Calculator.cs`, `Calculator.csproj`, `run.bat`.
3. Дважды кликните по `run.bat`.

### Особенности реализации:
*   **Безрамочный дизайн:** `WindowStyle="None"` + `AllowsTransparency` дают эффект современного приложения без стандартной белой рамки Windows. Окно можно таскать за любую область.
*   **Цветовая палитра:** Темно-серый фон (как в macOS/Windows 11 калькуляторах) с оранжевым акцентом на кнопке равенства.
*   **Единый файл:** Весь XAML заменен на code-behind генерацию UI. Это избавляет от необходимости настраивать сложные пути к ресурсам и позволяет собрать проект из одного `.cs` файла.
*   **Логика:** Поддерживает цепочки вычислений, проценты, смену знака, backspace и защиту от деления на ноль.

> ⚠️ **Требования:** На компьютере должен быть установлен **.NET 8 SDK** (или выше). Если используется другая версия, измените `<TargetFramework>` в `.csproj` на соответствующую (например, `net6.0-windows`).
